mapper.select:
SELECT id, username, password, name, email, phone, avatar, enable, organization_id,
       create_user, update_user, create_time, update_time
FROM sys_user
WHERE username = #{username}
  AND organization_id = #{organizationId}
LIMIT 1

SELECT role_id
FROM sys_user_role
WHERE user_id = #{userId}

SELECT u.id, u.username, u.password, u.name, u.email, u.phone, u.avatar, u.enable, u.organization_id, u.create_user, u.update_user, u.create_time, u.update_time FROM sys_user u
u.organization_id = #{organizationId}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.name LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
AND u.id IN (SELECT ou.user_id FROM sys_organization_user ou WHERE ou.department_id = #{departmentId})
AND u.enable = #{enable}
ORDER BY u.create_time DESC
